insert into destinations(slug,name,area,blurb,hero_image,gallery,default_nights,theme,places,rate_budget,rate_comfort,rate_premium,travel_train,travel_cab,travel_flight,activities,sort_order) values ('nepal','Nepal','Pokhara · Kathmandu','Lakeside Pokhara, the Manakamana cable car and the temples and stupas of Kathmandu, reached overland from Ranchi.','/img/trip-nepal.webp','[{"src":"/img/nepal-1.webp","caption":"Monastery and the Himalaya, Kathmandu valley"},{"src":"/img/nepal-2.webp","caption":"Durbar Square, Kathmandu"},{"src":"/img/nepal-3.webp","caption":"Swayambhunath stupa"},{"src":"/img/nepal-4.webp","caption":"Stupa below the Annapurnas"},{"src":"/img/nepal-5.webp","caption":"Annapurna region"},{"src":"/img/nepal-6.webp","caption":"Prayer wheels, Nepal Himalaya"},{"src":"/img/nepal-7.webp","caption":"Swayambhunath at dusk"}]'::jsonb,4,'["#1D4E89","#6FA8DC","#F4D35E"]'::jsonb,'["Pokhara","Kathmandu"]'::jsonb,1400,2600,5200,2600,2600,7800,'[{"id":"boat","n":"Phewa Lake boating","p":400,"where":"Pokhara"},{"id":"sarang","n":"Sarangkot sunrise","p":600,"where":"Pokhara"},{"id":"para","n":"Paragliding over Pokhara","p":7500,"where":"Pokhara"},{"id":"mana","n":"Manakamana cable car","p":1800,"where":"Manakamana"},{"id":"pashu","n":"Pashupatinath & stupas tour","p":700,"where":"Kathmandu"}]'::jsonb,0) on conflict (slug) do nothing;
