insert into destinations(slug,name,area,blurb,hero_image,gallery,default_nights,theme,places,rate_budget,rate_comfort,rate_premium,travel_train,travel_cab,travel_flight,activities,sort_order) values ('goa','Goa','Beaches & forts','North and South Goa: beaches, forts and a sunset cruise.','/img/dest-goa.webp','[{"src":"/img/goa-1.webp","caption":"North Goa from the cliffs"},{"src":"/img/goa-2.webp","caption":"Evening on the beach"},{"src":"/img/goa-3.webp","caption":"Rocks and surf, North Goa"},{"src":"/img/goa-4.webp","caption":"A quiet Goa cove"}]'::jsonb,4,'["#E76F51","#F4A261","#2A9D8F"]'::jsonb,'["North Goa","South Goa"]'::jsonb,1500,3000,6500,3200,3200,8500,'[{"id":"cruise","n":"Mandovi sunset cruise","p":900,"where":"North Goa"},{"id":"dudh","n":"Dudhsagar Falls jeep","p":2200,"where":"South Goa"},{"id":"water","n":"Water sports combo","p":1800,"where":"North Goa"},{"id":"fort","n":"Fort Aguada & old churches","p":400,"where":"North Goa"}]'::jsonb,5) on conflict (slug) do nothing;
insert into trips(slug,destination_id,title,route,summary,nights,image,itinerary,inclusions,exclusions,faqs) values ('nepal-trip-from-ranchi',(select id from destinations where slug='nepal'),'Nepal Trip from Ranchi','Ranchi → Raxaul → Pokhara → Manakamana → Kathmandu','A 5-day group trip from Ranchi to Nepal: Pokhara''s lake and sunrise points, the Manakamana cable car, and Kathmandu''s temples and stupas, with a Lavigo trip leader throughout.',4,'/img/trip-nepal.webp','[{"title":"Ranchi → Raxaul → Pokhara","text":"Cross the border at Birgunj, drive up to Pokhara, evening by the lake."},{"title":"Pokhara sightseeing","text":"Sunrise point, Phewa Lake boating, Davis Falls, Gupteshwor Cave."},{"title":"Pokhara → Manakamana → Kathmandu","text":"Cable car to Manakamana temple, then on to Kathmandu."},{"title":"Kathmandu sightseeing","text":"Pashupatinath, Boudhanath, Swayambhunath, evening in Thamel."},{"title":"Kathmandu → Raxaul → Ranchi","text":"Drive back to the border and the journey home."}]'::jsonb,'["Hotel stays, 4 nights","Breakfast & dinner","All travel on the route","Sightseeing as listed","Lavigo trip leader"]'::jsonb,'["Paragliding & optional activities","Lunch","Personal shopping"]'::jsonb,'[{"q":"What is included in the Nepal trip from Ranchi?","a":"The inclusions are listed on this page: hotel stays, the meals mentioned, travel on the route, sightseeing as listed and a Lavigo trip leader. Anything not listed under Included is extra."},{"q":"How do I book and how much do I pay upfront?","a":"Choose your departure, enter your details and your seats are held for you. You then confirm on WhatsApp with Lavigo and pay a 25% advance. The balance is due before you travel."},{"q":"How long are my seats held?","a":"Seats are held for 24 hours after you submit the booking form. If the advance is not paid in that time, the seats are released for other travellers."},{"q":"Where does the trip start and end?","a":"All Lavigo group trips start and end in Ranchi, with a trip leader travelling with the group."}]'::jsonb) on conflict (slug) do nothing;
insert into trips(slug,destination_id,title,route,summary,nights,image,itinerary,inclusions,exclusions,faqs) values ('darjeeling-winter-escape',(select id from destinations where slug='darjeeling'),'Darjeeling Winter Escape','Ranchi → NJP → Darjeeling → Mirik','A 4-day group trip from Ranchi to Darjeeling and Mirik: Tiger Hill sunrise, the toy train, tea estates and Mirik lake.',3,'/img/trip-darjeeling.webp','[{"title":"Ranchi → NJP → Darjeeling","text":"Overnight train, cab up the hills, Mall Road evening."},{"title":"Tiger Hill & toy train","text":"Sunrise at Tiger Hill, Batasia Loop, toy train joyride."},{"title":"Tea estates & Mirik","text":"Tea garden walk and tasting, Mirik lake."},{"title":"Darjeeling → NJP → Ranchi","text":"Drive down and train home."}]'::jsonb,'["Hotel stays, 3 nights","Breakfast & dinner","Train + cab","Sightseeing as listed","Lavigo trip leader"]'::jsonb,'["Lunch","Personal shopping"]'::jsonb,'[{"q":"What is included in the Darjeeling trip from Ranchi?","a":"The inclusions are listed on this page: hotel stays, the meals mentioned, travel on the route, sightseeing as listed and a Lavigo trip leader. Anything not listed under Included is extra."},{"q":"How do I book and how much do I pay upfront?","a":"Choose your departure, enter your details and your seats are held for you. You then confirm on WhatsApp with Lavigo and pay a 25% advance. The balance is due before you travel."},{"q":"How long are my seats held?","a":"Seats are held for 24 hours after you submit the booking form. If the advance is not paid in that time, the seats are released for other travellers."},{"q":"Where does the trip start and end?","a":"All Lavigo group trips start and end in Ranchi, with a trip leader travelling with the group."}]'::jsonb) on conflict (slug) do nothing;
insert into trips(slug,destination_id,title,route,summary,nights,image,itinerary,inclusions,exclusions,faqs) values ('north-sikkim-snow-trip',(select id from destinations where slug='sikkim'),'North Sikkim Snow Trip','Ranchi → NJP → Gangtok → Lachung','A 6-day group trip from Ranchi to Gangtok and Lachung: Tsomgo Lake, Baba Mandir, the Yumthang valley and Rumtek monastery, permits included.',5,'/img/trip-sikkim.webp','[{"title":"Ranchi → NJP → Gangtok","text":"Train and cab to Gangtok, MG Marg evening."},{"title":"Tsomgo Lake & Baba Mandir","text":"Frozen lake, Baba Mandir, back to Gangtok."},{"title":"Gangtok → Lachung","text":"Waterfalls on the way to Lachung."},{"title":"Yumthang Valley","text":"The valley of flowers, snow point if open."},{"title":"Lachung → Gangtok","text":"Drive back, Rumtek monastery."},{"title":"Gangtok → NJP → Ranchi","text":"Journey home."}]'::jsonb,'["Hotel stays, 5 nights","Breakfast & dinner","Permits","Train + cab","Lavigo trip leader"]'::jsonb,'["Zero Point extra","Lunch"]'::jsonb,'[{"q":"What is included in the North Sikkim trip from Ranchi?","a":"The inclusions are listed on this page: hotel stays, the meals mentioned, travel on the route, sightseeing as listed and a Lavigo trip leader. Anything not listed under Included is extra."},{"q":"How do I book and how much do I pay upfront?","a":"Choose your departure, enter your details and your seats are held for you. You then confirm on WhatsApp with Lavigo and pay a 25% advance. The balance is due before you travel."},{"q":"How long are my seats held?","a":"Seats are held for 24 hours after you submit the booking form. If the advance is not paid in that time, the seats are released for other travellers."},{"q":"Where does the trip start and end?","a":"All Lavigo group trips start and end in Ranchi, with a trip leader travelling with the group."}]'::jsonb) on conflict (slug) do nothing;
insert into trips(slug,destination_id,title,route,summary,nights,image,itinerary,inclusions,exclusions,faqs) values ('netarhat-weekend',(select id from destinations where slug='netarhat'),'Netarhat Weekend','Ranchi → Netarhat → Ranchi','A 3-day weekend group trip from Ranchi to Netarhat: Magnolia sunset point, Lodh Falls and Upper Ghaghri Falls.',2,null,'[{"title":"Ranchi → Netarhat","text":"Morning drive, Magnolia sunset point."},{"title":"Falls day","text":"Lodh Falls and Upper Ghaghri Falls."},{"title":"Sunrise & back to Ranchi","text":"Sunrise point and drive home."}]'::jsonb,'["Stay, 2 nights","All meals","AC cab from Ranchi","Lavigo trip leader"]'::jsonb,'["Personal expenses"]'::jsonb,'[{"q":"What is included in the Netarhat trip from Ranchi?","a":"The inclusions are listed on this page: hotel stays, the meals mentioned, travel on the route, sightseeing as listed and a Lavigo trip leader. Anything not listed under Included is extra."},{"q":"How do I book and how much do I pay upfront?","a":"Choose your departure, enter your details and your seats are held for you. You then confirm on WhatsApp with Lavigo and pay a 25% advance. The balance is due before you travel."},{"q":"How long are my seats held?","a":"Seats are held for 24 hours after you submit the booking form. If the advance is not paid in that time, the seats are released for other travellers."},{"q":"Where does the trip start and end?","a":"All Lavigo group trips start and end in Ranchi, with a trip leader travelling with the group."}]'::jsonb) on conflict (slug) do nothing;
